out=['<?xml version="1.0" encoding="UTF-8"?>','<Ads formatVersion="3" target="Avito.ru">'];rows=[]
for ci,(code,city,addr,area) in enumerate(CITIES):
  for d in DIRS:
    imgs=d['imgs'][ci%len(d['imgs']):]+d['imgs'][:ci%len(d['imgs'])]   # rotate cover per city
    title=d['titles'][ci].format(c=city)
    desc=f"{d['body']}<p>Работаем по {area}, выезжаем на объект. Опыт в сфере 10+ лет, гарантия, работа по договору. Ежедневно 09:00–20:00, минимальный заказ 10 000 ₽.</p><p>На фото — наши объекты: как было и как стало.</p><p>Напишите в сообщения — обсудим задачу и рассчитаем смету.</p>"
    out+=['<Ad>',f'<Id>{d["k"]}-{code}</Id>','<Category>Предложение услуг</Category>','<ServiceType>Строительство</ServiceType>',f'<ServiceSubtype>{d["sub"]}</ServiceSubtype>',f'<Title>{title}</Title>',f'<Description><![CDATA[{desc}]]></Description>',f'<Address>{addr}</Address>',*COMMON,d['extra'],'<Images>'+''.join(f'<Image url="{U.format(i)}"/>' for i in imgs)+'</Images>','</Ad>']
    rows.append(f'{city:15} | {title} | обложка {imgs[0]}')
out.append('</Ads>');open('feed_services.xml','w').write('\n'.join(out));print(len(rows),'ads');print('\n'.join(rows))
